<template><div class="option-page"><el-alert title="选择大盘期权池内合约：分时实时查询；点击日线研究后才查询并缓存日 K。" type="warning" :closable="false" show-icon /><el-form inline class="form"><el-form-item label="合约"><el-input v-model="thscode" style="width:280px" /></el-form-item><el-button type="primary" @click="loadIntraday">分时行情</el-button><el-button @click="loadDaily">日线研究</el-button></el-form><el-card v-if="intraday" shadow="never" header="当前分时"><el-table :data="intraday.item || []" max-height="300"><el-table-column label="时间"><template #default="{ row }">{{ time(row.timestamp) }}</template></el-table-column><el-table-column prop="price" label="价格" /><el-table-column prop="volume" label="成交量" /><el-table-column prop="turnover" label="成交额" /></el-table></el-card><el-card v-if="daily" shadow="never" header="日线研究"><el-table :data="daily.item || []" max-height="300"><el-table-column label="日期"><template #default="{ row }">{{ date(row.timestamp) }}</template></el-table-column><el-table-column prop="open_price" label="开" /><el-table-column prop="high_price" label="高" /><el-table-column prop="low_price" label="低" /><el-table-column prop="close_price" label="收" /><el-table-column prop="volume" label="量" /></el-table></el-card></div></template>
<script setup name="OptionMarket">
import { ref } from 'vue'; import { ElMessage } from 'element-plus'; import { getMarketOptionDailyResearch, getMarketOptionIntraday } from '@/api/future/option'
const thscode=ref('IO2610-C-4000.CFE'); const intraday=ref(null); const daily=ref(null); const time=value=>new Date(value).toLocaleString('zh-CN',{hour12:false}); const date=value=>new Date(value).toLocaleDateString('zh-CN')
function loadIntraday(){getMarketOptionIntraday(thscode.value).then(response=>{intraday.value=response.data}).catch(()=>ElMessage.error('分时行情查询失败'))} function loadDaily(){getMarketOptionDailyResearch(thscode.value).then(response=>{daily.value=response.data; ElMessage.success('日线已更新研究缓存')}).catch(()=>ElMessage.error('日线研究查询失败'))}
</script><style scoped>.option-page{padding:20px}.form{margin:16px 0}.el-card{margin-top:16px}</style>
